using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class BattlefieldRulesTests
{
 internal static WorldSession Start(){var p=NewGameWorldTests.Officer(role:StartTemplate.Retainer,site:"site:kofu",lord:"person:shingen");var setup=NewGameWorldTests.Setup([p]);return new(NewGameWorld.Create(setup.World,setup.Registered,p.Id,battlefieldPolicy:BattlefieldRules.Policy));}
 internal static void Good(CommandResult result)=>Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);
 internal static void Military(WorldSession s,NewMilitaryAction action,long amount=0)=>Good(s.DecideNewMilitary(new(new("request:battle-military/"+s.Revision),action,amount),s.PlayerControl,s.Revision));
 internal static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
 internal static void Pickup(WorldSession s){Military(s,NewMilitaryAction.Request);NewGameWorldTests.At(s,s.Seconds+2);Open(s);Military(s,NewMilitaryAction.Accept);NewGameWorldTests.At(s,s.Seconds+2);Open(s);Military(s,NewMilitaryAction.Pickup);}
 [Fact]public void EquipmentMovesActualDepotStockAndReturnsOnce(){var s=Start();Pickup(s);var w=s.DiagnosticSnapshot();var t=w.NewMilitary!.Terms;var unit=NewGameMilitary.UnitIdsFor(w)[0];var input=new BattlefieldInput(new("request:spears"),BattlefieldAction.Equip,unit,TroopKind.Spear,"spear",40);Good(s.ManageBattlefield(input,s.Revision));Assert.Equal(60,BattlefieldRules.Depot(s.DiagnosticSnapshot(),t.Owner,t.Site,"spear"));Assert.Equal(ResultCode.AlreadyAccepted,s.ManageBattlefield(input,s.Revision).Code);var restored=new WorldSession(ContractJson.Read<ContractWorld>(ContractJson.Write(s.DiagnosticSnapshot())));foreach(var x in new[]{s,restored})Good(x.ManageBattlefield(new(new("request:return-spears"),BattlefieldAction.ReturnGear,unit,TroopKind.Spear,"spear",40),x.Revision));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(restored.DiagnosticSnapshot()));Assert.Equal(100,BattlefieldRules.Depot(s.DiagnosticSnapshot(),t.Owner,t.Site,"spear"));}
 [Fact]public void GunsCannotBeEquippedWithoutCraftedPhysicalStock(){var s=Start();Pickup(s);var unit=NewGameMilitary.UnitIdsFor(s.DiagnosticSnapshot())[0];Assert.Equal(ResultCode.NotAvailable,s.ManageBattlefield(new(new("request:imaginary-guns"),BattlefieldAction.Equip,unit,TroopKind.Gun,"gun",10),s.Revision).Code);}
 [Fact]public void FormationChangesRealPositionsWithoutMultiplyingPeople(){var a=new FieldPoint(0,0);var b=new FieldPoint(20000,0);foreach(var kind in Enum.GetValues<FormationKind>()){var points=BattlefieldRules.Formation(a,b,kind);Assert.Equal(3,points.Distinct().Count());Assert.All(points,p=>Assert.InRange(p.Y,-10000,10000));}Assert.NotEqual(BattlefieldRules.Formation(a,b,FormationKind.Line),BattlefieldRules.Formation(a,b,FormationKind.Wedge));}
 [Fact]public void CasualtyPartitionConservesPeople(){for(int n=0;n<100;n++){var c=BattlefieldRules.SplitLosses(new("unit:test"),n,true,n/4);Assert.Equal(n,c.Dead+c.Wounded+c.Deserted+c.Recovered);}}
 [Fact]public void RealBattleConsumesArrowsAndRestoresTheSameFuture(){var s=NpcArmyTests.AtActualContact(permitted:true,sparse:true,battlefield:true,beforeDeploy:x=>{var unit=NewGameMilitary.UnitIdsFor(x.DiagnosticSnapshot())[1];Good(x.ManageBattlefield(new(new("request:bows"),BattlefieldAction.Equip,unit,TroopKind.Bow,"bow",30),x.Revision));Good(x.ManageBattlefield(new(new("request:arrows"),BattlefieldAction.Load,unit,Good:"arrow",Amount:60),x.Revision));});NewGameWorldTests.At(s,s.Seconds+6);var w=s.DiagnosticSnapshot();Assert.Contains(w.WorldClashes!.Steps,q=>q.Result.Expenses?.Any(e=>e.Good=="arrow")==true);var restored=new WorldSession(ContractJson.Read<ContractWorld>(ContractJson.Write(w)));foreach(var x in new[]{s,restored})NewGameWorldTests.At(x,w.ElapsedSeconds+3);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(restored.DiagnosticSnapshot()));Assert.InRange(BattlefieldRules.Carried(s.DiagnosticSnapshot(),NewGameMilitary.UnitIdsFor(w)[1],"arrow"),0,59);}
 [Fact]public void WoundedSoldiersConsumeRealRiceAndRecoverOnceAfterFiveDays(){
 var s=MedicalBattle();NewGameWorldTests.At(s,s.Seconds+2);Military(s,NewMilitaryAction.Enter);var w=s.DiagnosticSnapshot();var unit=NewGameMilitary.UnitIdsFor(w)[0];int wounded=BattlefieldRules.Casualties(w,unit,s.Seconds,w.CommitSequence+1).Wounded;Assert.True(wounded>0);long rice=w.Communities!.Accounts.Single(a=>a.Site==w.NewMilitary!.Terms.Site).HouseRice;var input=new BattlefieldInput(new("request:rest-wounded"),BattlefieldAction.Rest,unit,Amount:wounded);Good(s.ManageBattlefield(input,s.Revision));Assert.Equal(rice-3*wounded,s.DiagnosticSnapshot().Communities!.Accounts.Single(a=>a.Site==w.NewMilitary!.Terms.Site).HouseRice);Assert.Equal(ResultCode.AlreadyAccepted,s.ManageBattlefield(input,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(new(new("request:deploy-resting"),NewMilitaryAction.Deploy),s.PlayerControl,s.Revision).Code);
 var restored=new WorldSession(ContractJson.Read<ContractWorld>(ContractJson.Write(s.DiagnosticSnapshot())));long end=s.Seconds+5*86400;foreach(var x in new[]{s,restored})NewGameWorldTests.At(x,end);Assert.Equal(wounded,BattlefieldRules.Recovered(s.DiagnosticSnapshot(),unit,end));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(restored.DiagnosticSnapshot()));
 }
 static WorldSession MedicalBattle(){
 var p=NewGameWorldTests.Officer(role:StartTemplate.Daimyo,site:"site:fork");var setup=NewGameWorldTests.Setup([p],[new(p.Id,"org:medical-enemy",[p.Site],false)]);var w=NewGameWorld.Create(setup.World,setup.Registered,"person:nobunaga",worldArmyPolicy:NpcArmies.CompactCombatPolicy,battlefieldPolicy:BattlefieldRules.Policy,economyPolicy:CommunityEconomy.Policy);w.CommitSequence++;FactionStances.Apply(w,new(new("decision:medical-raid"),FactionStanceAction.DeclareHostile,new("org:medical-enemy"),new("org:oda"),0,1000000),new(p.Id));var s=new WorldSession(w);NewGameWorldTests.At(s,3);var journey=s.DiagnosticSnapshot().Branches!.Journeys.Single(j=>j.Actor.Value==p.Id);NewGameWorldTests.At(s,journey.Legs[^1].EndAt+1);Good(s.DecideNewMilitary(new(new("request:medical-army"),NewMilitaryAction.Request){AuthorityPolicy=NewGameMilitary.AuthorityContract,LedgerPolicy=NewGameMilitary.LedgerIdentityContract},s.PlayerControl,s.Revision));NewGameWorldTests.At(s,s.Seconds+2);Open(s);Military(s,NewMilitaryAction.Accept);NewGameWorldTests.At(s,s.Seconds+2);Open(s);Military(s,NewMilitaryAction.Pickup);Military(s,NewMilitaryAction.Load,100000);Military(s,NewMilitaryAction.Deploy);return s;
 }
}
